        #region Mutagen
        public IEnumerable<IFormLinkGetter> EnumerateFormLinks(ISoundDescriptorGetter obj, bool iterateNestedRecords = true)
        {
            foreach (var item in base.EnumerateFormLinks(obj, iterateNestedRecords))
            {
                yield return item;
            }
            if (FormLinkInformation.TryFactory(obj.Category, out var CategoryInfo))
            {
                yield return CategoryInfo;
            }
            if (FormLinkInformation.TryFactory(obj.AlternateSoundFor, out var AlternateSoundForInfo))
            {
                yield return AlternateSoundForInfo;
            }
            if (FormLinkInformation.TryFactory(obj.OutputModel, out var OutputModelInfo))
            {
                yield return OutputModelInfo;
            }
            foreach (var item in obj.Descriptors)
            {
                yield return FormLinkInformation.Factory(item);
            }
            if (FormLinkInformation.TryFactory(obj.PNAM, out var PNAMInfo))
            {
                yield return PNAMInfo;
            }
            if (FormLinkInformation.TryFactory(obj.QNAM, out var QNAMInfo))
            {
                yield return QNAMInfo;
            }
            if (obj.Conditions is {} ConditionsItem)
            {
                foreach (var item in ConditionsItem.WhereCastable<IConditionGetter, IFormLinkContainerGetter>()
                    .SelectMany((f) => f.EnumerateFormLinks(iterateNestedRecords)))
                {
                    yield return FormLinkInformation.Factory(item);
                }
            }
            if (FormLinkInformation.TryFactory(obj.INTV, out var INTVInfo))
            {
                yield return INTVInfo;
            }
            if (FormLinkInformation.TryFactory(obj.LNAM, out var LNAMInfo))
            {
                yield return LNAMInfo;
            }
            yield break;
        }
        
